"""The `record_list` output rows, emitted from the extension's own declarations.

Generated by `tools/gen_python_record_outputs.py` from each output's `fields` block.
**Do not edit by hand.** One frozen dataclass per row, `eq=False` for the same reason
the results are: an equality would compare `pint` quantities.
"""

from __future__ import annotations

from dataclasses import dataclass

from azoth.core.units import Q


@dataclass(frozen=True, slots=True, eq=False)
class ActivityCoefficientRow:
    """The activity coefficients the solve used: nine ions under the binary Pitzer, one `divalent` row otherwise."""

    #: The ion, or `divalent` under the models that carry one coefficient.
    ion: str

    #: The coefficient.
    activity_coefficient: float


@dataclass(frozen=True, slots=True, eq=False)
class BrineMixingPointRow:
    """One row per mixing fraction, from all brine A to all brine B."""

    #: the fraction of brine A in the mixture.
    fraction_a: float

    #: calcite's index.
    si_caco3: float

    #: barite's index.
    si_baso4: float

    #: gypsum's index.
    si_caso4: float

    #: celestite's index.
    si_srso4: float


@dataclass(frozen=True, slots=True, eq=False)
class DepositionSegmentRow:
    """One row per evaluated segment, in the profile's order."""

    #: the CaCO3 index at the segment's temperature and pressure.
    saturation_index: float

    #: the deposit mass over the segment's wall area and the service time.
    deposition_mass: Q

    #: the deposit thickness over the segment.
    thickness: Q


@dataclass(frozen=True, slots=True, eq=False)
class FlowlineScaleSegment:
    """The `N + 1` points, inlet first; a point's index is absent where its ions are."""

    #: the fraction of the flowline's length, zero at the inlet.
    distance_fraction: float

    #: the point's absolute temperature.
    temperature: Q

    #: the point's absolute pressure.
    pressure: Q

    #: calcite's index, absent where calcium or carbonate is.
    si_caco3: float | None

    #: barite's index.
    si_baso4: float | None

    #: celestite's index.
    si_srso4: float | None

    #: anhydrite's index.
    si_caso4: float | None

    #: siderite's index.
    si_feco3: float | None


@dataclass(frozen=True, slots=True, eq=False)
class KComponent:
    """one row per fitting supplied, in the order they were listed"""

    #: the fitting's id in the registry
    fitting_id: str

    #: equivalent length ratio, L_eq / D
    n_ld: float

    #: this fitting's resistance coefficient, f_t * n_ld
    k: float


@dataclass(frozen=True, slots=True, eq=False)
class MineralEquilibriumRow:
    """The registered minerals, in the class's order; a mineral whose ion is below the registration floor is absent rather than zero."""

    #: The mineral's formula, as the class names it.
    name: str

    #: The mineral's common name.
    common_name: str

    #: The index before anything precipitated.
    initial_saturation_index: float

    #: The index at the answer, against the frozen activity coefficients.
    final_saturation_index: float

    #: The product of the two ions' activity coefficients the solve used.
    activity_coefficient_product: float

    #: The precipitated amount per cubic metre of water.
    precipitated_amount: Q

    #: The precipitated mass per cubic metre of water.
    precipitated_mass: Q

    #: The precipitated mass over the stated water volume.
    total_precipitated_mass: Q

    #: Whether a limiting ion was exhausted while solid was present.
    limiting_ion_exhausted: bool


@dataclass(frozen=True, slots=True, eq=False)
class RemediationOptionRow:
    """The candidate remedies, ordered by descending effectiveness."""

    #: the canonical deposit key, `UNKNOWN` for the fallback.
    scale_type: str

    #: `MINERAL_SCALE`, `SCAVENGER_SOLIDS`, `ORGANIC_DEPOSIT` or `UNSPECIFIED`.
    category: str

    #: the dissolver or solvent chemistry.
    dissolver: str

    #: the recommended concentration or dilution, as the CSV states it.
    concentration: str

    #: the application method.
    method: str

    #: `HIGH`, `MEDIUM` or `LOW`.
    effectiveness: str

    #: the lower bound of the effective window.
    min_temperature: Q

    #: the upper bound of the effective window.
    max_temperature: Q

    #: the operational and safety cautions.
    cautions: str

    #: the informational standard reference.
    standard: str


@dataclass(frozen=True, slots=True, eq=False)
class ScaleControlRiskRow:
    """The inhibited risk index, one row per scale in the same order."""

    #: `CACO3`, `BASO4`, `SRSO4`, `CASO4` or `FECO3`.
    scale: str

    #: `SI + log10(max(1e-6, 1 - efficiency))`; absent where the index is.
    risk_index: float | None


@dataclass(frozen=True, slots=True, eq=False)
class ScaleControlRow:
    """The uninhibited indices, one row per scale in the class's order."""

    #: `CACO3`, `BASO4`, `SRSO4`, `CASO4` or `FECO3`.
    scale: str

    #: the index; absent where the water has none.
    saturation_index: float | None


@dataclass(frozen=True, slots=True, eq=False)
class StreamScaleMineralRow:
    """One row per registered mineral, in the equilibrium's order."""

    #: the mineral's formula.
    mineral: str

    #: the index before anything precipitated.
    initial_si: float

    #: the index at the answer.
    final_si: float

    #: the precipitated mass per cubic metre of water, 1699.4 mg/L as 1.6994 kg/m3.
    precipitated_mass: Q

    #: the precipitated mass times the aqueous throughput.
    scale_rate: Q


@dataclass(frozen=True, slots=True, eq=False)
class SubFraction:
    """The sub-fractions, in ascending sorting key. A lump that states no boiling point sorts by its molar mass, so the order is by key and not by the lumps' order."""

    #: The sub-fraction's name: its parent's, and the grid position appended to it.
    name: str

    #: The sub-fraction's mole amount. Its sum over one lump's sub-fractions is the lump's, so no mole is gained or lost.
    moles: Q

    #: The sub-fraction's molar mass, off the grid and after the one rescale. Its sum with the moles restores the lump's mass exactly.
    molar_mass: Q

    #: The sub-fraction's normal liquid density, which is its parent's unchanged.
    density: Q | None

    #: The sub-fraction's normal boiling point, spread with its molar mass. Absent where its parent states none.
    boiling_point: Q | None


@dataclass(frozen=True, slots=True, eq=False)
class WaterMixingResult:
    """One row per requested percentage, in the caller's order; an index is absent where its ions are."""

    #: the injection water's share this row was evaluated at.
    injection_water_percent: float

    #: calcite's index.
    si_caco3: float | None

    #: barite's index.
    si_baso4: float | None

    #: celestite's index.
    si_srso4: float | None

    #: anhydrite's index.
    si_caso4: float | None

    #: siderite's index.
    si_feco3: float | None
